// Generates typed endpoint definitions and Zod schemas from Alpaca's OpenAPI specs.
//
//   deno task generate            generate from the vendored specs in spec/ (checksums verified)
//   deno task generate --update   download fresh specs and rewrite spec/SHA256SUMS first
//
// Output goes to src/generated/<api>/{schemas,endpoints}.ts, formatted. Corrections belong in overrides.ts,
// never in the generated files.
import { type Overrides, overrides } from "./overrides.ts";
import {
  methods,
  type Operation,
  type Parameter,
  type RequestBody,
  type ResponseObject,
  type Schema,
  type Spec,
} from "./spec.ts";

const apis = [
  { key: "trading", api: "trading", file: "trading-api.json" },
  { key: "market", api: "data", file: "market-data-api.json" },
  { key: "broker", api: "broker", file: "broker-api.json" },
] as const;

const defaultSpecDir = new URL("../spec/", import.meta.url);
const defaultOutDir = new URL("../src/generated/", import.meta.url);
const sumsFile = (specDir: URL) => new URL("SHA256SUMS", specDir);

const header = (file: string) =>
  `// Generated by scripts/generate.ts from spec/${file}. Do not edit: change scripts/overrides.ts and regenerate.\n`;

// ── Specs and checksums ─────────────────────────────────────────────────────────────────────────

const sha256 = async (bytes: Uint8Array<ArrayBuffer>) =>
  Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256", bytes)), (b) => b.toString(16).padStart(2, "0"))
    .join("");

/** Downloads fresh specs and rewrites the checksums. Nothing is written unless every download succeeds. */
export const update = async (specDir = defaultSpecDir) => {
  const downloads = await Promise.all(apis.map(async ({ file }) => {
    const response = await fetch(`https://docs.alpaca.markets/openapi/${file}`);
    if (!response.ok) {
      await response.body?.cancel();
      throw new Error(`Downloading ${file}: ${response.status}`);
    }
    const bytes = new Uint8Array(await response.arrayBuffer());
    return { file, bytes, line: `${await sha256(bytes)}  ${file}` };
  }));
  for (const { file, bytes } of downloads) await Deno.writeFile(new URL(file, specDir), bytes);
  const lines = downloads.map(({ line }) => line).sort((a, b) => a.slice(66).localeCompare(b.slice(66)));
  await Deno.writeTextFile(sumsFile(specDir), lines.join("\n") + "\n");
};

export const verify = async (specDir = defaultSpecDir) => {
  const sums = new Map(
    (await Deno.readTextFile(sumsFile(specDir))).trim().split("\n").map((line) => [line.slice(66), line.slice(0, 64)]),
  );
  for (const { file } of apis) {
    const actual = await sha256(await Deno.readFile(new URL(file, specDir)));
    if (sums.get(file) !== actual) throw new Error(`spec/${file} doesn't match spec/SHA256SUMS`);
  }
};

// ── Names ───────────────────────────────────────────────────────────────────────────────────────

const words = (name: string) =>
  name.split(/[^A-Za-z0-9]+/).filter(Boolean).map((word) => word === word.toUpperCase() ? word.toLowerCase() : word);
const capitalize = (word: string) => word.charAt(0).toUpperCase() + word.slice(1);
const pascal = (name: string) => words(name).map(capitalize).join("");
const camel = (name: string) => {
  const result = pascal(name);
  return result.charAt(0).toLowerCase() + result.slice(1);
};

const reserved = new Set(
  "break case catch class const continue debugger default delete do else enum export extends false finally for function if import in instanceof new null return super switch this throw true try typeof var void while with yield let static implements interface package private protected public await"
    .split(" "),
);
const isIdentifier = (key: string) => /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key);
const propertyKey = (key: string) => isIdentifier(key) ? key : JSON.stringify(key);

const schemaName = (ref: string) => {
  const match = ref.match(/^#\/components\/schemas\/(.+)$/);
  if (!match) throw new Error(`Unsupported $ref ${ref}`);
  return match[1];
};

/** The first paragraph of a description, as a single-line JSDoc comment. */
const jsdoc = (text: string | undefined, indent = "") => {
  const paragraph = text?.trim().split(/\n\s*\n/)[0].replace(/\s+/g, " ").replaceAll("*/", "*\\/").trim();
  return paragraph ? `${indent}/** ${paragraph} */\n` : "";
};

// ── Schemas → Zod ───────────────────────────────────────────────────────────────────────────────

interface FlatObject {
  properties: Record<string, Schema>;
  required: string[];
  additionalProperties?: boolean | Schema;
}

class ZodWriter {
  constructor(readonly spec: Spec, readonly ref: (name: string) => string) {}

  resolve(schema: Schema): Schema {
    let current = schema;
    for (const seen = new Set<string>(); current.$ref;) {
      if (seen.has(current.$ref)) throw new Error(`Circular $ref ${current.$ref}`);
      seen.add(current.$ref);
      const target = this.spec.components.schemas[schemaName(current.$ref)];
      if (!target) throw new Error(`Missing schema ${current.$ref}`);
      current = target;
    }
    return current;
  }

  typesOf(schema: Schema): string[] {
    if (Array.isArray(schema.type)) return schema.type.filter((type) => type !== "null");
    if (schema.type) return schema.type === "null" ? [] : [schema.type];
    if (schema.properties || schema.additionalProperties) return ["object"];
    if (schema.items) return ["array"];
    return [];
  }

  isOnlyNull(schema: Schema) {
    return schema.type === "null" || (Array.isArray(schema.type) && schema.type.every((type) => type === "null"));
  }

  isNullable(schema: Schema): boolean {
    return Boolean(
      schema.nullable || schema["x-nullable"] || this.isOnlyNull(schema) ||
        (Array.isArray(schema.type) && schema.type.includes("null")) || schema.enum?.includes(null) ||
        (schema.oneOf ?? schema.anyOf)?.some((option) => this.isOnlyNull(option)) ||
        schema.allOf?.some((member) => this.isTrivial(member) && this.isNullable(member)),
    );
  }

  /** A schema that only states a type (and documentation), adding nothing a sibling doesn't. */
  isTrivial(schema: Schema) {
    return !(schema.$ref || schema.enum || schema.const !== undefined || schema.format || schema.properties ||
      schema.items || schema.allOf || schema.oneOf || schema.anyOf || schema.additionalProperties);
  }

  zod(schema: Schema): string {
    const base = this.base(schema);
    return this.isNullable(schema) && !base.endsWith(".nullable()") && base !== "Z.null()"
      ? `${base}.nullable()`
      : base;
  }

  base(schema: Schema): string {
    if (schema.$ref) return this.ref(schemaName(schema.$ref));
    if (schema.allOf) return this.allOf(schema);
    const options = schema.oneOf ?? schema.anyOf;
    // With properties alongside, oneOf/anyOf only add "one of these is required" constraints, which
    // are left to the server
    if (options && !schema.properties) return this.union(options, schema.discriminator?.propertyName);
    if (schema.const !== undefined && schema.const !== null) return `Z.literal(${JSON.stringify(schema.const)})`;
    if (schema.enum) return this.enum(schema.enum);
    if (this.isOnlyNull(schema)) return "Z.null()";
    const types = this.typesOf(schema);
    if (types.length > 1) return `Z.union([${types.map((type) => this.typed(schema, type)).join(", ")}])`;
    return this.typed(schema, types[0]);
  }

  enum(values: unknown[]) {
    const nonNull = values.filter((value) => value !== null);
    if (!nonNull.length) return "Z.null()";
    if (nonNull.length === 1) return `Z.literal(${JSON.stringify(nonNull[0])})`;
    if (nonNull.every((value) => typeof value === "string")) return `Z.enum(${JSON.stringify(nonNull)})`;
    return `Z.union([${nonNull.map((value) => `Z.literal(${JSON.stringify(value)})`).join(", ")}])`;
  }

  typed(schema: Schema, type: string | undefined): string {
    switch (type) {
      case "string":
        if (schema.format === "date-time") return "Z.iso.datetime({ offset: true })";
        if (schema.format === "date") return "Z.iso.date()";
        return "Z.string()";
      case "integer":
      case "number":
        // Alpaca sends decimals as strings
        if (schema.format === "decimal") return "Z.string()";
        // 64-bit IDs (crypto trade ids) exceed 2^53, where `.int()` rejects them; JSON.parse has already
        // rounded them anyway
        if (schema.format === "int64" || schema.format === "uint64") return "Z.number()";
        return type === "integer" ? "Z.number().int()" : "Z.number()";
      case "boolean":
        return "Z.boolean()";
      case "array":
        return `Z.array(${schema.items ? this.zod(schema.items) : "Z.unknown()"})`;
      case "object":
        return this.object({
          properties: schema.properties ?? {},
          required: schema.required ?? [],
          additionalProperties: schema.additionalProperties,
        });
      case undefined:
        return "Z.unknown()";
      default:
        throw new Error(`Unsupported type ${type}`);
    }
  }

  object({ properties, required, additionalProperties }: FlatObject) {
    const extra = typeof additionalProperties === "object" ? this.zod(additionalProperties) : undefined;
    const entries = Object.entries(properties);
    if (!entries.length) return `Z.record(Z.string(), ${extra ?? "Z.unknown()"})`;
    const fields = entries.map(([key, value]) =>
      `${jsdoc(value.description)}${propertyKey(key)}: ${this.zod(value)}${required.includes(key) ? "" : ".optional()"}`
    );
    const object = `Z.object({\n${fields.join(",\n")}\n})`;
    return extra ? `${object}.catchall(${extra})` : object;
  }

  /** An object's own properties, as an allOf member. */
  ownPart(schema: Schema): Schema[] {
    return schema.properties
      ? [{
        properties: schema.properties,
        required: schema.required,
        additionalProperties: schema.additionalProperties,
      }]
      : [];
  }

  allOf(schema: Schema): string {
    const members = [...schema.allOf!, ...this.ownPart(schema)];
    const meaningful = members.filter((member) => !this.isTrivial(member));
    if (meaningful.length === 0) return this.zod({ ...members[0], allOf: undefined });
    if (meaningful.length === 1) return this.zod(meaningful[0]);
    const flat = this.flatten(members);
    if (flat) return this.object(flat);
    return meaningful.map((member) => this.zod(member)).reduce((left, right) => `Z.intersection(${left}, ${right})`);
  }

  /** Merges allOf members into one object, or returns undefined when one of them isn't an object. */
  flatten(members: Schema[]): FlatObject | undefined {
    const result: FlatObject = { properties: {}, required: [] };
    for (const member of members) {
      const resolved = this.resolve(member);
      const types = this.typesOf(resolved);
      let part: FlatObject | undefined;
      if (resolved.allOf) part = this.flatten([...resolved.allOf, ...this.ownPart(resolved)]);
      else if (resolved.oneOf || resolved.anyOf || resolved.enum) return undefined;
      else if (types.length === 1 && types[0] === "object") {
        part = {
          properties: resolved.properties ?? {},
          required: resolved.required ?? [],
          additionalProperties: resolved.additionalProperties,
        };
      } else if (types.length === 0 && this.isTrivial(resolved)) continue;
      if (!part) return undefined;
      Object.assign(result.properties, part.properties);
      result.required.push(...part.required.filter((key) => !result.required.includes(key)));
      result.additionalProperties = part.additionalProperties ?? result.additionalProperties;
    }
    return result;
  }

  union(options: Schema[], key: string | undefined): string {
    const nonNull = options.filter((option) => !this.isOnlyNull(option));
    if (nonNull.length === 1) return this.zod(nonNull[0]);
    const parts = nonNull.map((option) => this.zod(option)).join(", ");
    return key && this.isDiscriminated(key, nonNull)
      ? `Z.discriminatedUnion(${JSON.stringify(key)}, [${parts}])`
      : `Z.union([${parts}])`;
  }

  /** Whether every option is an object whose `key` is a required enum, with no value shared between options. */
  isDiscriminated(key: string, options: Schema[]) {
    const seen = new Set<unknown>();
    for (const option of options) {
      const flat = this.flatten([option]);
      const property = flat?.properties[key] && this.resolve(flat.properties[key]);
      const values = property?.enum ?? (property?.const !== undefined ? [property.const] : undefined);
      if (!flat || !values || !flat.required.includes(key)) return false;
      for (const value of values) {
        if (seen.has(value)) return false;
        seen.add(value);
      }
    }
    return true;
  }
}

// ── schemas.ts ──────────────────────────────────────────────────────────────────────────────────

const refsIn = (value: unknown, found = new Set<string>()): Set<string> => {
  if (Array.isArray(value)) value.forEach((item) => refsIn(item, found));
  else if (value && typeof value === "object") {
    for (const [key, item] of Object.entries(value)) {
      if (key === "$ref" && typeof item === "string") found.add(schemaName(item));
      else if (key !== "example" && key !== "examples") refsIn(item, found);
    }
  }
  return found;
};

const schemaIdentifiers = (spec: Spec) => {
  const identifiers = new Map<string, string>();
  const used = new Map<string, string>();
  for (const name of Object.keys(spec.components.schemas)) {
    const identifier = pascal(name);
    if (!identifier || /^[0-9]/.test(identifier)) throw new Error(`Can't name schema ${name}`);
    const clash = used.get(identifier);
    if (clash) throw new Error(`Schemas ${clash} and ${name} both become ${identifier}`);
    used.set(identifier, name);
    identifiers.set(name, identifier);
  }
  return identifiers;
};

const generateSchemas = (spec: Spec, file: string) => {
  const identifiers = schemaIdentifiers(spec);
  const emitted = new Set<string>();
  const ordered: string[] = [];
  const visiting = new Set<string>();
  const visit = (name: string) => {
    if (emitted.has(name) || visiting.has(name)) return;
    visiting.add(name);
    for (const dependency of refsIn(spec.components.schemas[name])) visit(dependency);
    visiting.delete(name);
    emitted.add(name);
    ordered.push(name);
  };
  Object.keys(spec.components.schemas).forEach(visit);

  const done = new Set<string>();
  // A reference to a schema not yet emitted can only come from a cycle
  const writer = new ZodWriter(spec, (name) => {
    const identifier = `${identifiers.get(name)}Schema`;
    return done.has(name) ? identifier : `Z.lazy(() => ${identifier})`;
  });

  const blocks = ordered.map((name) => {
    const schema = spec.components.schemas[name];
    const identifier = identifiers.get(name)!;
    const code = writer.zod(schema);
    done.add(name);
    return `${jsdoc(schema.description)}export const ${identifier}Schema = ${code};\n` +
      `export type ${identifier} = Z.output<typeof ${identifier}Schema>;\n`;
  });

  return `${header(file)}import { Z } from "../../external.ts";\n\n${blocks.join("\n")}`;
};

// ── endpoints.ts ────────────────────────────────────────────────────────────────────────────────

interface Skipped {
  operationId: string;
  reason: string;
}

const deref = <T extends { $ref?: string }>(
  spec: Spec,
  value: T,
  kind: "parameters" | "responses" | "requestBodies",
) => {
  if (!value.$ref) return value;
  const match = value.$ref.match(new RegExp(`^#/components/${kind}/(.+)$`));
  const target = match && spec.components[kind]?.[match[1]];
  if (!target) throw new Error(`Unresolvable $ref ${value.$ref}`);
  return target as T;
};

const dateOrDateTime: Schema = {
  anyOf: [{ type: "string", format: "date" }, { type: "string", format: "date-time" }],
};

/**
 * Many date filters are declared `date-time` while their description says "RFC-3339 or YYYY-MM-DD",
 * and the API does take both. The description wins: plain dates are what most callers pass.
 */
const documentedAsDate = ({ schema, description }: Parameter) =>
  schema?.type === "string" && schema.format === "date-time" && /\bYYYY-MM-DD\b/.test(description ?? "");

const generateEndpoints = (spec: Spec, file: string, api: string, skipped: Skipped[]) => {
  const identifiers = schemaIdentifiers(spec);
  const writer = new ZodWriter(spec, (name) => `S.${identifiers.get(name)}Schema`);
  const sections = new Map<string, string[]>();
  const names = new Map<string, string>();

  for (const [path, item] of Object.entries(spec.paths)) {
    for (const method of methods) {
      const operation = item[method];
      if (!operation) continue;
      const { operationId } = operation;

      const success = Object.keys(operation.responses).filter((code) => /^2\d\d$/.test(code));
      const responses = success.map((code) => deref<ResponseObject>(spec, operation.responses[code], "responses"));
      const contentTypes = [...new Set(responses.flatMap((response) => Object.keys(response.content ?? {})))];
      if (!success.length) {
        const codes = Object.keys(operation.responses).join(", ");
        skipped.push({ operationId, reason: `no 2xx response (declares ${codes})` });
        continue;
      }
      const unsupported = contentTypes.filter((type) => type !== "application/json");
      if (unsupported.length) {
        skipped.push({ operationId, reason: `returns ${unsupported.join(", ")}` });
        continue;
      }

      const identifier = reserved.has(camel(operationId)) ? `${camel(operationId)}Endpoint` : camel(operationId);
      const clash = names.get(identifier);
      if (clash) throw new Error(`Operations ${clash} and ${operationId} both become ${identifier}`);
      names.set(identifier, operationId);

      const parameters = new Map<string, Parameter>();
      for (const parameter of [...(item.parameters ?? []), ...(operation.parameters ?? [])]) {
        const resolved = deref<Parameter>(spec, parameter, "parameters");
        parameters.set(`${resolved.in}:${resolved.name}`, resolved);
      }
      const group = (location: Parameter["in"], allOptional = false) => {
        const list = [...parameters.values()].filter((parameter) => parameter.in === location);
        if (!list.length) return "Z.never()";
        const fields = list.map((parameter) => {
          const schema = parameter.schema ?? {};
          const types = writer.typesOf(writer.resolve(schema));
          if (location !== "header" && (types.includes("object") || (types.includes("array") && location === "path"))) {
            throw new Error(`${operationId}: unsupported ${location} parameter ${parameter.name}`);
          }
          const optional = !allOptional && (parameter.required || location === "path") ? "" : ".optional()";
          return `${propertyKey(parameter.name)}: ${
            writer.zod(documentedAsDate(parameter) ? dateOrDateTime : schema)
          }${optional}`;
        });
        return `Z.object({ ${fields.join(", ")} })`;
      };

      const placeholders = [...path.matchAll(/\{(\w+)\}/g)].map((match) => match[1]).sort();
      const pathParameters = [...parameters.values()].filter((p) => p.in === "path").map((p) => p.name).sort();
      if (placeholders.join() !== pathParameters.join()) {
        throw new Error(`${operationId}: path ${path} doesn't match its parameters ${pathParameters}`);
      }

      const requestBody = operation.requestBody && deref<RequestBody>(spec, operation.requestBody, "requestBodies");
      let body = "Z.never()";
      if (requestBody) {
        const media = requestBody.content?.["application/json"];
        if (!media) {
          throw new Error(`${operationId}: unsupported request body ${Object.keys(requestBody.content ?? {})}`);
        }
        // OpenAPI's default is optional, but the specs almost never set `required` and nearly every
        // body is needed: only an explicit `required: false` (see overrides.ts) makes one optional
        body = writer.zod(media.schema ?? {}) + (requestBody.required === false ? ".optional()" : "");
      }

      const media = responses[0].content?.["application/json"];
      // A GET always returns something. Where the spec declares its 200 without content, void would
      // make the client throw the data away, so it comes back untyped instead
      const contentless = method === "get" && success[0] !== "204" ? "Z.unknown()" : "Z.void()";
      const response = success[0] === "204" || !media ? contentless : writer.zod(media.schema ?? {});
      const okStatus = success.length === 1 ? success[0] : `[${success.join(", ")}]`;
      const headers = group("header", true);

      const code = `${jsdoc(operation.description ?? operation.summary)}export const ${identifier} = {
        name: ${JSON.stringify(operation.summary ?? operationId)},
        api: "${api}",
        method: "${method.toUpperCase()}",
        path: ${JSON.stringify(path.replace(/^\//, ""))},

        params: ${group("path")},
        query: ${group("query")},${headers === "Z.never()" ? "" : `\nheaders: ${headers},`}
        body: ${body},
        response: ${response},

        okStatus: ${okStatus},
      } satisfies Endpoint;\n`;

      const tag = operation.tags?.[0] ?? "Other";
      sections.set(tag, [...(sections.get(tag) ?? []), code]);
    }
  }

  const body = [...sections].map(([tag, codes]) => `// ── ${tag} ──\n\n${codes.join("\n")}`).join("\n");
  return `${header(file)}import { Z } from "../../external.ts";\nimport type { Endpoint } from "../../client.ts";\n` +
    `import * as S from "./schemas.ts";\n\n${body}`;
};

// ── Main ────────────────────────────────────────────────────────────────────────────────────────

const applyOverrides = (spec: Spec, { schemas = {}, parameters = {}, operations = {} }: Overrides, file: string) => {
  for (const [name, patch] of Object.entries(schemas)) {
    const schema = spec.components.schemas[name];
    if (!schema) throw new Error(`overrides: no schema ${name} in ${file}`);
    patch(schema);
  }
  for (const [name, patch] of Object.entries(parameters)) {
    const parameter = spec.components.parameters?.[name];
    if (!parameter) throw new Error(`overrides: no parameter ${name} in ${file}`);
    patch(parameter);
  }
  const byId = new Map<string, Operation>();
  for (const item of Object.values(spec.paths)) {
    for (const method of methods) {
      const operation = item[method];
      if (operation) byId.set(operation.operationId, operation);
    }
  }
  for (const [operationId, patch] of Object.entries(operations)) {
    const operation = byId.get(operationId);
    if (!operation) throw new Error(`overrides: no operation ${operationId} in ${file}`);
    patch(operation);
  }
};

/** `deno fmt` with the repo's settings, wherever `dir` is. */
const format = async (dir: URL) => {
  const config = new URL("../deno.json", import.meta.url);
  const { success } = await new Deno.Command(Deno.execPath(), {
    args: ["fmt", "-q", "--config", config.pathname, dir.pathname],
  }).spawn().status;
  if (!success) throw new Error(`deno fmt failed on ${dir.pathname}`);
};

/** Verifies the vendored specs, then writes formatted `<api>/{schemas,endpoints}.ts` under `outDir`. */
export const generate = async (
  { specDir = defaultSpecDir, outDir = defaultOutDir, log = console.log }: {
    specDir?: URL;
    outDir?: URL;
    log?: (line: string) => void;
  } = {},
) => {
  await verify(specDir);
  for (const { key, api, file } of apis) {
    const spec: Spec = JSON.parse(await Deno.readTextFile(new URL(file, specDir)));
    applyOverrides(spec, overrides[key], file);
    const skipped: Skipped[] = [];
    const schemas = generateSchemas(spec, file);
    let endpoints = generateEndpoints(spec, file, api, skipped);
    if (skipped.length) {
      endpoints += `\n// Not generated (out of scope: only JSON responses are supported):\n` +
        skipped.map(({ operationId, reason }) => `// - ${operationId}: ${reason}\n`).join("");
    }
    const dir = new URL(`${key}/`, outDir);
    await Deno.mkdir(dir, { recursive: true });
    await Deno.writeTextFile(new URL("schemas.ts", dir), schemas);
    await Deno.writeTextFile(new URL("endpoints.ts", dir), endpoints);
    const count = (endpoints.match(/satisfies Endpoint/g) ?? []).length;
    log(
      `${key}: ${count} endpoints, ${Object.keys(spec.components.schemas).length} schemas, ${skipped.length} skipped`,
    );
  }
  await format(outDir);
};

if (import.meta.main) {
  const unknown = Deno.args.find((arg) => arg !== "--update");
  if (unknown !== undefined) {
    console.error(`generate: unknown argument ${unknown}\nusage: deno task generate [--update]`);
    Deno.exit(1);
  }
  if (Deno.args.includes("--update")) await update();
  await generate();
}
